insert into public.legal_documents (doc_type, version, title, content) values ('acik_riza_pazarlama_bildirim', 1, 'Açık Rıza Metni — Anlık Bildirim ile Kampanya ve Duyuru İletileri', $legal$# Açık Rıza Metni — Anlık Bildirim ile Kampanya ve Duyuru İletileri

